<script lang="ts">
  import { onMount } from 'svelte';
  import SettingsHeader from '$lib/components/SettingsHeader.svelte';
  import { api } from '$lib/api';
  import type { Dish, Food, MealCategory, MealPlan, Recipe, RecipeIngredient } from '$lib/types';

  type Tab = 'categories' | 'foods' | 'recipes' | 'plans';
  let tab: Tab = 'plans'; let loading = true; let saving = false; let error = ''; let notice = '';
  let categories: MealCategory[] = []; let foods: Food[] = []; let recipes: Recipe[] = []; let plans: MealPlan[] = []; let dishes: Dish[] = [];
  let categoryName = ''; let foodName = ''; let foodKcal = ''; let recipeName = ''; let recipeServings = '1'; let planName = ''; let presetName = ''; let presetKcal = ''; let presetSlot = '1';
  let editingRecipeId = ''; let recipeFoodId = ''; let recipeQuantity = '100'; let recipeDraft: RecipeIngredient[] = [];
  let editingPlanId = ''; let planCategoryId = ''; let planRecipeId = ''; let planPortion = '1'; let planWeekdays: number[] = []; let planDraft: MealPlan['items'] = [];
  async function load() { loading = true; error = ''; try { [categories, foods, recipes, plans, dishes] = await Promise.all([api.getMealCategories(true), api.getFoods(), api.getRecipes(), api.getMealPlans(), api.getDishes()]); } catch { error = 'Die Mahlzeiten-Konfiguration konnte nicht geladen werden. Prüfe die Verbindung und versuche es erneut.'; } finally { loading = false; } }
  onMount(load);
  async function save(action: () => Promise<unknown>, success: string) { error = ''; notice = ''; saving = true; try { const result = await action(); if (!result) throw new Error('empty'); notice = success; await load(); } catch { error = 'Änderung konnte nicht gespeichert werden. Deine Eingabe bleibt erhalten; versuche es erneut.'; } finally { saving = false; } }
  function addCategory() { const name = categoryName.trim(); if (!name) { error = 'Bitte gib einen Namen für die Kategorie ein.'; return; } save(async () => { const r = await api.createMealCategory({ name, sort_order: categories.length, is_active: true }); if (r) categoryName = ''; return r; }, 'Kategorie gespeichert.'); }
  function moveCategory(index: number, direction: -1 | 1) { const next = [...categories]; const target = index + direction; if (target < 0 || target >= next.length) return; [next[index], next[target]] = [next[target], next[index]]; save(() => api.reorderMealCategories(next.map((c) => c.id)), 'Reihenfolge gespeichert.'); }
  function setCategoryActive(category: MealCategory) { save(() => api.updateMealCategory(category.id, { is_active: !category.is_active, updated_at: category.updated_at }), category.is_active ? 'Kategorie ausgeblendet.' : 'Kategorie eingeblendet.'); }
  function addFood() { const name = foodName.trim(); const kcal = Number(foodKcal); if (!name || foodKcal === '' || !Number.isFinite(kcal) || kcal < 0) { error = 'Name und gültige kcal pro 100 g sind erforderlich.'; return; } save(async () => { const r = await api.createFood({ name, kcal }); if (r) { foodName = ''; foodKcal = ''; } return r; }, 'Lebensmittel gespeichert.'); }
  function addRecipe() { const name = recipeName.trim(); const servings = Number(recipeServings); if (!name || !Number.isFinite(servings) || servings <= 0) { error = 'Name und mindestens eine Portion sind erforderlich.'; return; } save(async () => { const r = await api.createRecipe({ name, status: 'draft', servings, ingredients: [] }); if (r) { recipeName = ''; recipeServings = '1'; } return r; }, 'Rezeptentwurf gespeichert.'); }
  function addPreset() { const name = presetName.trim(); const kcal = Number(presetKcal); const slot = Number(presetSlot); if (!name || !Number.isFinite(kcal) || kcal < 0) { error = 'Preset-Name und kcal sind erforderlich.'; return; } save(async () => { const r = await api.createDish({ name, kcal, slot, source: 'manual' }); if (r) { presetName = ''; presetKcal = ''; } return r; }, 'Preset gespeichert und im Tagesplan verfügbar.'); }
  function addPlan() { const name = planName.trim(); if (!name) { error = 'Bitte gib einen Namen für den Plan ein.'; return; } save(async () => { const r = await api.createMealPlan({ name, is_active: plans.length === 0, items: [] }); if (r) planName = ''; return r; }, 'Plan gespeichert.'); }
  function archiveRecipe(recipe: Recipe) { save(() => api.updateRecipe(recipe.id, { status: recipe.status === 'archived' ? 'active' : 'archived', updated_at: recipe.updated_at }), recipe.status === 'archived' ? 'Rezept reaktiviert.' : 'Rezept archiviert.'); }
  function editRecipe(recipe: Recipe) { editingRecipeId = recipe.id; recipeDraft = recipe.ingredients.map((item) => ({ ...item })); recipeFoodId = ''; recipeQuantity = '100'; }
  function addRecipeFood() { const quantity = Number(recipeQuantity); if (!recipeFoodId || !Number.isFinite(quantity) || quantity <= 0) { error = 'Wähle ein Lebensmittel und eine gültige Grammmenge.'; return; } recipeDraft = [...recipeDraft, { food_id: recipeFoodId, quantity, unit: 'g', sort_order: recipeDraft.length }]; recipeFoodId = ''; }
  function removeRecipeIngredient(index: number) { recipeDraft = recipeDraft.filter((_, current) => current !== index).map((item, sort_order) => ({ ...item, sort_order })); }
  function saveRecipeIngredients(recipe: Recipe) { save(() => api.updateRecipe(recipe.id, { ingredients: recipeDraft.map(({ id: _id, ...item }) => item), expected_updated_at: recipe.updated_at }), 'Rezeptzutaten gespeichert.'); editingRecipeId = ''; }
  function activatePlan(plan: MealPlan) { save(() => api.updateMealPlan(plan.id, { is_active: true, updated_at: plan.updated_at }), 'Plan aktiviert.'); }
  function editPlan(plan: MealPlan) { editingPlanId = plan.id; planDraft = plan.items.map((item, sort_order) => ({ ...item, sort_order })); planCategoryId = categories.find((category) => category.is_active)?.id ?? ''; planRecipeId = ''; planPortion = '1'; planWeekdays = []; }
  function togglePlanDay(day: number) { planWeekdays = planWeekdays.includes(day) ? planWeekdays.filter((current) => current !== day) : [...planWeekdays, day].sort(); }
  function addPlanItem() { const portion = Number(planPortion); if (!planCategoryId || !Number.isFinite(portion) || portion <= 0) { error = 'Kategorie und gültige Portion sind erforderlich.'; return; } planDraft = [...planDraft, { category_id: planCategoryId, recipe_id: planRecipeId || null, name: null, portion, weekdays: planWeekdays.length ? planWeekdays : null, sort_order: planDraft.length }]; planRecipeId = ''; planWeekdays = []; }
  function removePlanItem(index: number) { planDraft = planDraft.filter((_, current) => current !== index).map((item, sort_order) => ({ ...item, sort_order })); }
  function savePlanItems(plan: MealPlan) { save(() => api.updateMealPlan(plan.id, { items: planDraft.map(({ id: _id, ...item }) => item), expected_updated_at: plan.updated_at }), 'Plan gespeichert.'); editingPlanId = ''; }
</script>

<svelte:head><title>FitTrack – Mahlzeiten konfigurieren</title></svelte:head>
<div class="page">
  <SettingsHeader title="Mahlzeiten" subtitle="Presets und Wochenplan" />
  <p class="intro">Die Mahlzeiten selbst bleiben im gemeinsamen Tagesplan. Hier legst du nur ihre Presets, Zutaten und den Wochenplan fest.</p>
  <div class="tabs" role="tablist" aria-label="Mahlzeiten konfigurieren">
    <button role="tab" aria-selected={tab === 'plans'} class:active={tab === 'plans'} onclick={() => tab = 'plans'}>Wochenplan</button><button role="tab" aria-selected={tab === 'recipes'} class:active={tab === 'recipes'} onclick={() => tab = 'recipes'}>Mahlzeiten-Presets</button><button role="tab" aria-selected={tab === 'foods'} class:active={tab === 'foods'} onclick={() => tab = 'foods'}>Lebensmittel</button><button role="tab" aria-selected={tab === 'categories'} class:active={tab === 'categories'} onclick={() => tab = 'categories'}>Kategorien</button>
  </div>
  {#if error}<div class="message error" role="alert">{error}</div>{/if}{#if notice}<div class="message success" role="status">{notice}</div>{/if}
  {#if loading}<div class="loading" role="status">Lade Mahlzeiten-Konfiguration…</div>
  {:else if tab === 'categories'}
    <section class="section-card"><div class="section-header"><h2>Mahlzeitenkategorien</h2><span>{categories.filter((c) => c.is_active).length} aktiv</span></div><p class="section-copy">Kategorien strukturieren deine Tagesansicht. Pro Kategorie sind mehrere Einträge möglich.</p><form class="form-row" onsubmit={(e) => { e.preventDefault(); addCategory(); }}><input aria-label="Name der neuen Kategorie" placeholder="z. B. Pre-Workout" bind:value={categoryName} maxlength="80" /><button class="primary" disabled={saving}>Hinzufügen</button></form><div class="list">{#each categories as category, index (category.id)}<div class:muted={!category.is_active} class="row"><div class="row-main"><strong>{category.name}</strong><small>{category.is_active ? 'sichtbar' : 'ausgeblendet'}</small></div><div class="row-actions"><button aria-label={`${category.name} nach oben`} disabled={index === 0 || saving} onclick={() => moveCategory(index, -1)}>↑</button><button aria-label={`${category.name} nach unten`} disabled={index === categories.length - 1 || saving} onclick={() => moveCategory(index, 1)}>↓</button><button disabled={saving} onclick={() => setCategoryActive(category)}>{category.is_active ? 'Ausblenden' : 'Einblenden'}</button></div></div>{:else}<div class="empty">Noch keine Kategorien. Lege zuerst die Mahlzeiten an, die zu deinem Alltag passen.</div>{/each}</div></section>
  {:else if tab === 'foods'}
    <section class="section-card"><div class="section-header"><h2>Lebensmittel</h2><span>{foods.filter((food) => food.source !== 'import').length} gespeichert</span></div><p class="section-copy">Nährwerte werden pro 100 g geführt. Mahlzeiten-Presets erscheinen bewusst nicht hier, sondern im eigenen Bereich.</p><form class="form-row food-form" onsubmit={(e) => { e.preventDefault(); addFood(); }}><input aria-label="Name des Lebensmittels" placeholder="Lebensmittel" bind:value={foodName} maxlength="120" /><input aria-label="Kilokalorien pro 100 Gramm" type="number" min="0" step="0.1" placeholder="kcal / 100 g" bind:value={foodKcal} /><button class="primary" disabled={saving}>Hinzufügen</button></form><div class="list">{#each foods.filter((food) => food.source !== 'import') as food (food.id)}<div class="row"><div class="row-main"><strong>{food.name}</strong><small>{food.kcal ?? '–'} kcal / 100 g {#if food.source}· {food.source}{/if}</small></div></div>{:else}<div class="empty">Noch keine eigenen Lebensmittel.</div>{/each}</div></section>
  {:else if tab === 'recipes'}
    <section class="section-card"><div class="section-header"><h2>Mahlzeiten-Presets</h2><span>{dishes.length} sofort nutzbar</span></div><p class="section-copy">Ein Preset ist ein wiederverwendbares Gericht. Es steht in der Tagesliste über „Preset“ sofort zur Auswahl.</p><form class="form-row food-form" onsubmit={(e) => { e.preventDefault(); addPreset(); }}><input aria-label="Name des Presets" placeholder="z. B. Protein-Porridge" bind:value={presetName} maxlength="120" /><input aria-label="Kilokalorien des Presets" type="number" min="0" step="1" placeholder="kcal" bind:value={presetKcal} /><select aria-label="Mahlzeit" bind:value={presetSlot}><option value="1">Frühstück</option><option value="2">Mittag</option><option value="3">Snack</option><option value="4">Abendessen</option></select><button class="primary" disabled={saving}>Anlegen</button></form><div class="list">{#each dishes as dish (dish.id)}<div class="row"><div class="row-main"><strong>{dish.name}</strong><small>{dish.kcal ?? '–'} kcal · {['', 'Frühstück', 'Mittag', 'Snack', 'Abendessen'][dish.slot ?? 0] || 'alle Mahlzeiten'}</small></div></div>{:else}<div class="empty">Noch keine Presets. Lege ein Gericht an; Details und Portionen lassen sich in der Tagesliste wählen.</div>{/each}</div></section>
  {:else}
    <section class="section-card"><div class="section-header"><h2>Wochenplan</h2><span>{plans.length} gespeichert</span></div><p class="section-copy">Wie beim Sportprogramm legst du wiederkehrende Presets je Wochentag fest. Der Tagesplan bleibt dabei die eine gemeinsame Liste.</p><form class="form-row" onsubmit={(e) => { e.preventDefault(); addPlan(); }}><input aria-label="Name des Mahlzeitenplans" placeholder="z. B. Arbeitstage" bind:value={planName} maxlength="120" /><button class="primary" disabled={saving}>Plan anlegen</button></form><div class="list">{#each plans as plan (plan.id)}{#if editingPlanId === plan.id}<form class="recipe-editor" onsubmit={(e) => { e.preventDefault(); savePlanItems(plan); }}><strong>{plan.name}: geplante Mahlzeiten</strong>{#each planDraft as item, index}<div class="draft-line"><span>{categories.find((category) => category.id === item.category_id)?.name ?? 'Kategorie'} · {item.recipe_id ? recipes.find((recipe) => recipe.id === item.recipe_id)?.name ?? 'Preset' : item.name ?? 'Freier Platz'} · {item.portion ?? 1} Portion</span><button type="button" onclick={() => removePlanItem(index)}>Entfernen</button></div>{:else}<small>Keine geplanten Mahlzeiten</small>{/each}<div class="weekday-picker" aria-label="Wochentage">{#each ['Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'] as label, day}<button type="button" class:active={planWeekdays.includes(day)} onclick={() => togglePlanDay(day)}>{label}</button>{/each}<small>Keine Auswahl = täglich</small></div><div class="form-row"><select aria-label="Kategorie" bind:value={planCategoryId}>{#each categories.filter((category) => category.is_active) as category}<option value={category.id}>{category.name}</option>{/each}</select><select aria-label="Preset" bind:value={planRecipeId}><option value="">Freier Platz</option>{#each recipes.filter((recipe) => recipe.status !== 'archived') as recipe}<option value={recipe.id}>{recipe.name.replace('Legacy template: ', '')}</option>{/each}</select><input aria-label="Portionen" type="number" min="0.001" step="0.001" bind:value={planPortion} /><button type="button" onclick={addPlanItem}>Hinzufügen</button></div><div class="row-actions"><button class="primary" disabled={saving}>Speichern</button><button type="button" onclick={() => editingPlanId = ''}>Abbrechen</button></div></form>{:else}<div class="row"><div class="row-main"><strong>{plan.name}</strong><small>{plan.items.length} geplante Plätze {#if plan.is_active}· aktiv{/if}</small></div><div class="row-actions"><button disabled={saving} onclick={() => editPlan(plan)}>Bearbeiten</button>{#if !plan.is_active}<button disabled={saving} onclick={() => activatePlan(plan)}>Aktivieren</button>{/if}</div></div>{/if}{:else}<div class="empty">Noch kein Wochenplan. Mahlzeiten können auch direkt im Tagesplan erfasst werden.</div>{/each}</div></section>
  {/if}
</div>
<style>
  .page { display:flex; flex-direction:column; gap:12px; padding-bottom:24px; } .intro,.section-copy { margin:0; color:var(--text-dim); font-size:13px; line-height:1.45; } .tabs { display:flex; overflow-x:auto; gap:6px; padding-bottom:2px; } .tabs button,.row-actions button { min-height:36px; border:1px solid var(--border-2); border-radius:8px; background:var(--card); color:var(--text-dim); padding:6px 10px; cursor:pointer; font:inherit; font-size:12px; white-space:nowrap; } .tabs button.active,.weekday-picker button.active { background:var(--green); border-color:var(--green); color:#07120a; font-weight:700; } button:focus-visible,input:focus-visible { outline:2px solid var(--blue); outline-offset:2px; } button:disabled { opacity:.45; cursor:not-allowed; } .section-card { background:var(--card); border:1px solid var(--border); border-radius:12px; overflow:hidden; } .section-header { display:flex; justify-content:space-between; gap:12px; align-items:baseline; padding:14px 14px 8px; } h2 { margin:0; font-size:15px; } .section-header span { color:var(--text-faint); font-size:12px; } .section-copy { padding:0 14px 12px; } .form-row { display:flex; gap:8px; padding:0 14px 14px; } input { min-width:0; flex:1; min-height:40px; border:1px solid var(--border-2); border-radius:8px; background:var(--card-2); color:var(--text); padding:0 10px; font:inherit; font-size:14px; } .food-form input:last-of-type { max-width:130px; } .primary { min-height:40px; border:0; border-radius:8px; background:var(--green); color:#07120a; padding:0 12px; font-weight:700; cursor:pointer; white-space:nowrap; } .list { border-top:1px solid var(--border); } .row { display:flex; align-items:center; gap:10px; padding:11px 14px; border-bottom:1px solid var(--border); } .row:last-child { border-bottom:0; } .row.muted { opacity:.55; } .row-main { display:flex; min-width:0; flex:1; flex-direction:column; gap:2px; } strong { overflow:hidden; text-overflow:ellipsis; white-space:nowrap; font-size:14px; } small { color:var(--text-faint); font-size:12px; } .row-actions { display:flex; gap:4px; align-items:center; } .row-actions button { padding:5px 7px; min-height:32px; } .recipe-editor { display:grid; gap:10px; padding:14px; } .draft-line { display:flex; justify-content:space-between; gap:8px; font-size:13px; } .weekday-picker { display:flex; align-items:center; gap:4px; flex-wrap:wrap; padding:0 14px 12px; } .weekday-picker button { width:34px; height:32px; border:1px solid var(--border-2); border-radius:7px; background:var(--card-2); color:var(--text-dim); cursor:pointer; font:inherit; font-size:11px; } .weekday-picker small { margin-left:4px; } .empty,.loading,.message { padding:14px; font-size:13px; line-height:1.4; } .empty,.loading { color:var(--text-faint); } .message { border-radius:8px; } .message.error { color:var(--red); background:color-mix(in srgb,var(--red) 12%,transparent); } .message.success { color:var(--green); background:color-mix(in srgb,var(--green) 12%,transparent); } @media (max-width:480px) { .form-row { flex-wrap:wrap; } .form-row input { flex-basis:150px; } .form-row .primary { flex:1; } .food-form input:last-of-type { max-width:none; } }
</style>
